import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"肥胖症诊疗指南（2024年版）","description":"国家卫健委《肥胖症诊疗指南（2024年版）》要点整理：国内首部肥胖多学科诊疗权威指南的诊断标准与治疗路径。","frontmatter":{"title":"肥胖症诊疗指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-10","source_url":"https://www.nhc.gov.cn/yzygj/c100068/202410/18966b78087d44429f934a2ef028b027.shtml","status":"现行","tags":["肥胖症","诊疗","临床指南","多学科"],"reviewed":false,"description":"国家卫健委《肥胖症诊疗指南（2024年版）》要点整理：国内首部肥胖多学科诊疗权威指南的诊断标准与治疗路径。"},"headers":[],"relativePath":"guides/obesity-clinical-2024.md","filePath":"guides/obesity-clinical-2024.md"}'),i={name:"guides/obesity-clinical-2024.md"};function l(o,t,s,h,n,g){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="肥胖症诊疗指南-2024年版" tabindex="-1">肥胖症诊疗指南（2024年版） <a class="header-anchor" href="#肥胖症诊疗指南-2024年版" aria-label="Permalink to &quot;肥胖症诊疗指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>这是一部面向医务人员的<strong>临床诊疗规范</strong>，本页仅帮助患者和家属理解&quot;规范诊疗长什么样&quot;。本站不构成诊疗建议，诊疗决策<strong>请遵医嘱</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/yzygj/c100068/202410/18966b78087d44429f934a2ef028b027.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>医疗卫生人员；普通读者可用它了解肥胖症的规范诊疗路径——就医时知道有哪些规范手段、该挂什么科。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p>国内首部肥胖多学科诊疗（MDT）权威指南：系统阐述病因学、流行病学、定义、诊断标准、分型分期，以及行为心理干预、运动干预、临床营养治疗、药物治疗、外科手术治疗、中医药治疗等多种手段。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=1" target="_blank" rel="noreferrer">原文·一</a>）</p><table tabindex="0"><thead><tr><th>关键标准</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>中心性肥胖</td><td>腰围 <strong>男 ≥90cm / 女 ≥85cm</strong>（亚洲人）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=5" target="_blank" rel="noreferrer">四(二)</a></td></tr><tr><td>重度肥胖症</td><td>BMI 达到 <strong>37.5 且 &lt;50kg/m²</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=5" target="_blank" rel="noreferrer">四(二)</a></td></tr><tr><td>脂肪供能比（医学营养治疗）</td><td><strong>不超过 20%～25%</strong>，烹调用油 ≤25g/日</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=71" target="_blank" rel="noreferrer">医学营养治疗</a></td></tr><tr><td>运动处方</td><td>减重期每周 <strong>150～420 分钟</strong>有氧耐力运动；体重维持期 <strong>每周 200～300 分钟</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=28" target="_blank" rel="noreferrer">运动干预</a></td></tr><tr><td>抗阻训练</td><td><strong>每周 2～3 次</strong>，针对主要肌群</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=28" target="_blank" rel="noreferrer">运动干预</a></td></tr></tbody></table><h2 id="了解诊疗路径" tabindex="-1">了解诊疗路径 <a class="header-anchor" href="#了解诊疗路径" aria-label="Permalink to &quot;了解诊疗路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>内容</th><th>出处</th></tr></thead><tbody><tr><td>定义与诊断</td><td>肥胖症定义、诊断标准、分型、分期</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=4" target="_blank" rel="noreferrer">四</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=5" target="_blank" rel="noreferrer">四(二)</a></td></tr><tr><td>相关疾病</td><td>肥胖症相关合并症的系统梳理</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=10" target="_blank" rel="noreferrer">四(五)</a></td></tr><tr><td>治疗手段</td><td>行为心理干预、运动干预、临床营养治疗、药物治疗、外科手术治疗、中医药治疗</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=71" target="_blank" rel="noreferrer">治疗章节</a></td></tr><tr><td>多学科协作</td><td>MDT 诊疗模式与个体化方案</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-clinical-2024.pdf#page=1" target="_blank" rel="noreferrer">一</a></td></tr></tbody></table><h2 id="给患者和家属的提示" tabindex="-1">给患者和家属的提示 <a class="header-anchor" href="#给患者和家属的提示" aria-label="Permalink to &quot;给患者和家属的提示&quot;">​</a></h2><ul><li>治疗决策（用药、手术）必须由医生做出；了解标准是为了识别&quot;不规范&quot;。</li><li>饮食与生活方式部分，配合本站<a href="/SageRelay/guides/obesity-2024.html">《成人肥胖食养指南（2024年版）》</a>词条阅读。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 10 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/yzygj/c100068/202410/18966b78087d44429f934a2ef028b027.shtml" target="_blank" rel="noreferrer">卫健委通知页</a></td></tr></tbody></table>',15)])])}const p=e(i,[["render",l]]);export{b as __pageData,p as default};
